/* Sambecca's Closet review storefront. No live orders or payments are accepted. */
'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('en-NG',{style:'currency',currency:'NGN',maximumFractionDigits:0}).format(n);
const clone=x=>JSON.parse(JSON.stringify(x));
const store={read(k,f){try{return JSON.parse(localStorage.getItem(k))??f}catch{return f}},write(k,v){try{localStorage.setItem(k,JSON.stringify(v));return true}catch{return false}}};
let data=store.read('sc-catalogue-v1',clone(window.CLOSET_DATA));
if(!validCatalogue(data))data=clone(window.CLOSET_DATA);
let cart=store.read('sc-bag-v1',[]),wishlist=store.read('sc-wishlist-v1',[]);
if(!Array.isArray(cart))cart=[];if(!Array.isArray(wishlist))wishlist=[];
const categories=['Corporate Tops','Trousers','Two-Piece Sets','Business Casual'];
const iconPaths={bag:'<path d="M5 7h14l1 14H4L5 7Z"/><path d="M8 8V6a4 4 0 0 1 8 0v2"/>',heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 22v-2a8 8 0 0 1 16 0v2"/>',menu:'<path d="M3 6h18M3 12h18M3 18h18"/>',close:'<path d="m5 5 14 14M19 5 5 19"/>',leaf:'<path d="M20 3C8 1 1 8 6 16c8 6 15-1 14-13Z"/><path d="m4 21 11-11"/>',spark:'<path d="m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3 3-7Z"/>',tag:'<path d="m2 12 10 10 10-10V2H12L2 12Z"/><circle cx="17" cy="7" r="1"/>',check:'<path d="m4 12 5 5L20 6"/>',chat:'<path d="M21 11a9 9 0 0 1-9 9c-2 0-3-.3-5-1l-5 2 2-5a9 9 0 1 1 17-5Z"/><path d="M7 10h10M7 14h6"/>',grid:'<path d="M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z"/>',list:'<path d="M8 5h13M8 12h13M8 19h13M3 5h1M3 12h1M3 19h1"/>',filter:'<path d="M3 5h18M6 12h12M9 19h6"/>',zoom:'<circle cx="10" cy="10" r="7"/><path d="m15 15 6 6M7 10h6M10 7v6"/>',share:'<path d="M12 16V2m-5 5 5-5 5 5M5 12H3v10h18V12h-2"/>'};
function icon(n){return `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${iconPaths[n]||iconPaths.spark}</svg>`}
function routeLink(path){return path}
function safeUrl(s){try{const u=new URL(s,location.origin);return ['http:','https:'].includes(u.protocol)?esc(s):''}catch{return ''}}
function picture(src,alt,extra=''){return `<img src="${safeUrl(src)}" alt="${esc(alt)}" ${extra} referrerpolicy="no-referrer">`}
function totalStock(p){return Object.values(p.stock).reduce((s,v)=>s+Object.values(v).reduce((a,n)=>a+n,0),0)}
function product(id){return data.products.find(p=>p.id===id)}
function available(p,color,size){return p?.stock[color]?.[size]||0}
function cartKey(id,color,size){return `${id}|${color}|${size}`}
function validCatalogue(d){return !!d&&d.version===1&&d.settings&&typeof d.settings.email==='string'&&typeof d.settings.heroImage==='string'&&typeof d.settings.storyImage==='string'&&Array.isArray(d.products)&&d.products.length<=200&&new Set(d.products.map(p=>p.id)).size===d.products.length&&d.products.every(p=>p&&/^[a-zA-Z0-9_-]+$/.test(p.id)&&typeof p.name==='string'&&categoriesForValidation().includes(p.category)&&Number.isFinite(p.price)&&p.price>0&&Number.isFinite(p.oldPrice)&&p.oldPrice>=0&&Array.isArray(p.images)&&p.images.length>0&&p.images.every(u=>typeof u==='string'&&/^(https?:\/\/|\/assets\/)/.test(u))&&Array.isArray(p.sizes)&&p.sizes.length>0&&p.sizes.every(s=>typeof s==='string')&&Array.isArray(p.colors)&&p.colors.length>0&&p.colors.every(c=>typeof c.name==='string'&&/^#[0-9a-fA-F]{6}$/.test(c.hex)&&p.stock?.[c.name]&&p.sizes.every(s=>Number.isInteger(p.stock[c.name][s])&&p.stock[c.name][s]>=0)))}
function categoriesForValidation(){return ['Corporate Tops','Trousers','Two-Piece Sets','Business Casual']}
function sanitizeCart(){cart=cart.filter(c=>c&&typeof c.key==='string'&&Number.isInteger(c.qty)&&c.qty>0&&product(c.id)&&available(product(c.id),c.color,c.size)>0).map(c=>({...c,qty:Math.min(c.qty,available(product(c.id),c.color,c.size))}));wishlist=wishlist.filter(id=>product(id));saveBag()}
function saveBag(){store.write('sc-bag-v1',cart);store.write('sc-wishlist-v1',wishlist)}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3600)}
function shell(){const path=location.pathname;$('#shell').innerHTML=`<div class="notice">${esc(data.settings.announcement)} <span>Preview collection · sample styles & prices</span></div><header class="header"><div class="wrap header-inner"><button class="icon-btn mobile-only" data-action="menu" aria-label="Open menu">${icon('menu')}</button><a class="brand" href="/" aria-label="Sambecca’s Closet home">${picture('/assets/logo.png','Sambecca’s Closet. Elevate your work wardrobe.','width="896" height="277"')}</a><nav class="nav" aria-label="Main navigation">${[['/','Home'],['/shop','Shop'],['/shop?collection=new','New Arrivals'],['/shop?collection=best','Best Sellers'],['/about','Our Story'],['/contact','Contact']].map(([u,t])=>`<a href="${u}" class="${path===u?'active':''}">${t}</a>`).join('')}</nav><div class="header-tools"><button class="icon-btn" data-action="search" aria-label="Search products">${icon('search')}</button><a class="icon-btn" href="/wishlist" aria-label="Wishlist">${icon('heart')}${wishlist.length?`<span class="count">${wishlist.length}</span>`:''}</a><a class="icon-btn account" href="/account" aria-label="Customer account">${icon('user')}</a><button class="icon-btn" data-action="bag" aria-label="Shopping bag, ${cart.reduce((a,c)=>a+c.qty,0)} items">${icon('bag')}${cart.length?`<span class="count">${cart.reduce((a,c)=>a+c.qty,0)}</span>`:''}</button></div></div></header>`;
$('#footer').innerHTML=`<footer class="footer"><div class="wrap"><div class="footer-grid"><div><a class="brand" href="/">${picture('/assets/logo.png','Sambecca’s Closet','loading="lazy" width="896" height="277"')}</a><p>Affordable elegance.<br>For the woman who means business.</p><p style="margin-top:15px">Lagos, Nigeria</p></div><div><h4>The Collection</h4>${categories.map(c=>`<a href="/shop?category=${encodeURIComponent(c)}">${esc(c)}</a>`).join('')}<a href="/shop?collection=new">New Arrivals</a><a href="/shop?collection=best">Best Sellers</a><a href="/shop?collection=sale">Sale</a></div><div><h4>Here to Help</h4>${[['about','Our Story'],['contact','Contact'],['faq','FAQs'],['size-guide','Size Guide'],['delivery','Delivery Information'],['returns','Returns & Exchanges']].map(([u,t])=>`<a href="/${u}">${t}</a>`).join('')}</div><div><h4>Let’s Connect</h4><a href="${safeUrl(data.settings.instagram)}" target="_blank" rel="noopener">Instagram · @sambeccaCloset</a><a href="${safeUrl(data.settings.tiktok)}" target="_blank" rel="noopener">TikTok · @sambeccas.closet</a><a href="mailto:${esc(data.settings.email)}">${esc(data.settings.email)}</a><button class="text-link" data-action="support">Chat with us</button><p class="preview-caption">Stock photography and sample products are used in this review version.</p></div></div><div class="footer-end"><span>© ${new Date().getFullYear()} Sambecca’s Closet. All rights reserved.</span><span><a style="display:inline" href="/privacy">Privacy</a> &nbsp; / &nbsp; <a style="display:inline" href="/terms">Terms</a> &nbsp; / &nbsp; <a style="display:inline" href="/admin">Owner preview</a></span></div></div></footer><button class="support-float" data-action="support">${icon('chat')} <span>Chat with us</span></button>`}
function card(p){const sold=totalStock(p)===0;return `<article class="product-card"><div class="product-image"><a href="/product/${p.id}" aria-label="View ${esc(p.name)}">${picture(p.images[0],`${p.name}, illustrative stock photograph`,'loading="lazy" width="750" height="1000"')}${p.images[1]?picture(p.images[1],`Alternative styling inspiration for ${p.name}`,'class="secondary" loading="lazy" width="750" height="1000"'):''}</a><span class="badge ${sold?'sold':''}">${sold?'Out of stock':p.oldPrice>p.price?'Sale':p.newArrival?'New arrival':'The workwear edit'}</span><button class="icon-btn wish ${wishlist.includes(p.id)?'saved':''}" data-action="wish" data-id="${p.id}" aria-label="${wishlist.includes(p.id)?'Remove from':'Add to'} wishlist: ${esc(p.name)}" aria-pressed="${wishlist.includes(p.id)}">${icon('heart')}</button><button class="quick" data-action="quick" data-id="${p.id}">${sold?'View piece':'Choose options'}</button></div><div class="product-info"><a class="product-name" href="/product/${p.id}">${esc(p.name)}</a><p class="product-category">${esc(p.category)}</p><p class="price">${money(p.price)}${p.oldPrice>p.price?`<del>${money(p.oldPrice)}</del>`:''}</p><div class="swatches">${p.colors.map(c=>`<span class="swatch" style="background:${esc(c.hex)}" title="${esc(c.name)}"></span>`).join('')}<span class="sizes">${p.sizes.map(esc).join(' · ')}</span></div></div></article>`}
function productSection(title,subtitle,arr,url){return `<section class="section"><div class="wrap"><div class="section-title"><div><p class="eyebrow gold">${subtitle}</p><h2>${title}</h2></div><a class="text-link" href="${url}">View the edit</a></div><div class="product-grid">${arr.map(card).join('')}</div></div></section>`}
function benefits(){return `<div class="wrap"><div class="benefits">${[['leaf','Thoughtfully selected','Pieces chosen with quality in mind.'],['tag','Attainable elegance','Look polished without overspending.'],['spark','Made for your day','Comfort that goes with your ambition.'],['check','Confidence, always','Feel as good as you look.']].map(([i,h,p])=>`<div class="benefit">${icon(i)}<h3>${h}</h3><p>${p}</p></div>`).join('')}</div></div>`}
function newsletter(){return `<section class="newsletter"><p class="eyebrow">A little style in your inbox</p><h2>Your next favourite piece<br>could be one email away.</h2><p>New arrivals, styling inspiration and special offers from Sambecca’s Closet.</p><form id="newsletter-form"><label class="skip" for="newsletter-email">Your email address</label><input id="newsletter-email" name="email" type="email" required placeholder="Your email address" autocomplete="email"><button type="submit">JOIN THE LIST</button></form><p style="font-size:.72rem">Preview only. Subscription opens when the store launches.</p></section>`}
function home(){const catImages=categories.map(c=>data.products.find(p=>p.category===c)?.images[0]);return `<section class="hero"><div class="hero-copy"><p class="eyebrow">For the woman who means business</p><h1>Elevate your<br>work <em>wardrobe.</em></h1><p class="hero-sub">Stylish. Comfortable. Work-ready.</p><p>Elegant, affordable corporate wear for the modern working woman. Because confidence looks good on you.</p><div class="hero-actions"><a class="btn" href="/shop">Shop the collection</a><a class="text-link" href="/shop?collection=new">Explore new arrivals</a></div><div class="hero-foot">Quality · Comfort · Elegance · Confidence</div></div><div class="hero-photo">${picture(data.settings.heroImage,'Editorial stock photograph of a woman in a tailored beige suit','fetchpriority="high" width="1200" height="1600"')}<div class="photo-label">THE WORKWEAR EDIT <span>SAMBECCA’S CLOSET</span></div></div></section><div class="marquee"><span>From your desk to your next big moment</span><i>✧</i><span>Polished pieces. Real-life prices.</span><i>✧</i><span>Based in Lagos</span></div><section class="section"><div class="wrap"><div class="section-title"><div><p class="eyebrow gold">Your wardrobe, thoughtfully curated</p><h2>Find your kind of polished.</h2></div></div><div class="category-grid">${categories.map((c,i)=>`<a class="category-card" href="/shop?category=${encodeURIComponent(c)}">${picture(catImages[i]||data.settings.heroImage,`${c} styling inspiration`,'loading="lazy" width="750" height="1000"')}<div class="category-copy"><h3>${c}</h3><span>EXPLORE COLLECTION</span></div></a>`).join('')}</div></div></section>${productSection('New pieces. Fresh confidence.','Just added to the closet',data.products.filter(p=>p.newArrival).slice(0,4),'/shop?collection=new')}<section class="editorial"><div class="editorial-image">${picture(data.settings.storyImage,'Editorial stock portrait of a professional woman in a brown blazer','loading="lazy" width="1000" height="1000"')}</div><div class="editorial-copy"><p class="eyebrow">More than getting dressed</p><h2>For your ambition.<br>And your everyday.</h2><p>Finding workwear should be the easy part of your day. Sambecca’s Closet began with a simple wish: clothes that look smart, feel comfortable and fit your life, without stretching your budget.</p><a class="text-link" href="/about">The story behind the closet</a></div></section>${benefits()}${productSection('Meet your wardrobe favourites.','The best-seller preview edit',data.products.filter(p=>p.bestSeller).slice(0,4),'/shop?collection=best')}<section class="section tinted"><div class="wrap"><div class="section-title"><div><p class="eyebrow gold">A little inspiration</p><h2>The workday, styled.</h2></div><a class="text-link" href="${safeUrl(data.settings.instagram)}" target="_blank" rel="noopener">@sambeccaCloset</a></div><div class="social-grid">${[data.products[0],data.products[2],data.products[6],data.products[4]].filter(Boolean).map(p=>`<a href="/product/${p.id}">${picture(p.images[0],`${p.name} styling inspiration`,'loading="lazy" width="600" height="600"')}</a>`).join('')}</div><p class="preview-caption">Editorial inspiration. Visit our Instagram for the brand’s latest posts.</p><div class="split-cta"><h2>Ready to elevate<br>your work wardrobe?</h2><a class="btn" href="/shop">Find your perfect look</a></div></div></section>${newsletter()}`}
let filters={cats:[],size:'',color:'',max:'',available:false,sort:'new',view:'grid',query:''};
function initFilters(){const q=new URLSearchParams(location.search);filters={cats:q.get('category')?[q.get('category')]:[],size:'',color:'',max:'',available:false,sort:q.get('collection')==='best'?'best':'new',view:'grid',query:q.get('q')||''}}
function shop(){const q=new URLSearchParams(location.search), collection=q.get('collection');let title=collection==='new'?'New arrivals':collection==='best'?'The best-seller edit':collection==='sale'?'A little extra value':filters.cats.length===1?filters.cats[0]:'The workwear collection';return `<div class="wrap"><div class="page-intro"><p class="eyebrow">Your next favourite piece</p><h1>${esc(title)}</h1><p>Easy to wear. Beautiful to style. Explore the preview collection.</p></div><div class="shop-layout"><aside class="filters" id="filters" aria-label="Product filters"><div class="filter-group"><h3>Category</h3>${categories.map(c=>`<label><input type="checkbox" name="category" value="${esc(c)}" ${filters.cats.includes(c)?'checked':''}>${c}</label>`).join('')}</div><div class="filter-group"><h3>Size</h3><select id="size-filter" aria-label="Filter by size"><option value="">All sizes</option>${[...new Set(data.products.flatMap(p=>p.sizes))].map(s=>`<option>${esc(s)}</option>`).join('')}</select></div><div class="filter-group"><h3>Colour</h3><select id="color-filter" aria-label="Filter by colour"><option value="">All colours</option>${[...new Set(data.products.flatMap(p=>p.colors.map(c=>c.name)))].map(c=>`<option>${esc(c)}</option>`).join('')}</select></div><div class="filter-group"><h3>Price</h3><select id="price-filter" aria-label="Maximum price"><option value="">All prices</option><option value="25000">Up to ₦25,000</option><option value="40000">Up to ₦40,000</option><option value="60000">Up to ₦60,000</option></select></div><div class="filter-group"><h3>Availability</h3><label><input type="checkbox" id="availability-filter">In stock only</label></div><div class="filter-group"><button class="text-link" data-action="clear-filters">Clear all filters</button></div></aside><div><div class="catalogue-toolbar"><button class="text-link mobile-filter-toggle" data-action="filters">${icon('filter')} Filters</button><span id="result-count" role="status"></span><div class="toolbar-controls"><label class="skip" for="sort-select">Sort products</label><select id="sort-select"><option value="new">Newest first</option><option value="best">Best sellers first</option><option value="low">Price: low to high</option><option value="high">Price: high to low</option><option value="name">Name: A to Z</option></select><button class="icon-btn" data-action="grid" aria-label="Grid view" aria-pressed="true">${icon('grid')}</button><button class="icon-btn" data-action="list" aria-label="List view" aria-pressed="false">${icon('list')}</button></div></div><div class="chips" id="filter-chips"></div><div class="product-grid" id="shop-results"></div></div></div></div>`}
function updateResults(){const q=new URLSearchParams(location.search),coll=q.get('collection');let arr=data.products.filter(p=>(coll!=='new'||p.newArrival)&&(coll!=='best'||p.bestSeller)&&(coll!=='sale'||p.oldPrice>p.price)&&(!filters.cats.length||filters.cats.includes(p.category))&&(!filters.size||p.sizes.includes(filters.size))&&(!filters.color||p.colors.some(c=>c.name===filters.color))&&(!filters.max||p.price<=+filters.max)&&(!filters.available||(filters.color?(filters.size?available(p,filters.color,filters.size)>0:Object.values(p.stock[filters.color]||{}).some(n=>n>0)):(filters.size?p.colors.some(c=>available(p,c.name,filters.size)>0):totalStock(p)>0)))&&(!filters.query||`${p.name} ${p.category}`.toLowerCase().includes(filters.query.toLowerCase())));
arr.sort((a,b)=>filters.sort==='low'?a.price-b.price:filters.sort==='high'?b.price-a.price:filters.sort==='name'?a.name.localeCompare(b.name):filters.sort==='best'?Number(b.bestSeller)-Number(a.bestSeller):Number(b.newArrival)-Number(a.newArrival));
$('#result-count').textContent=`${arr.length} ${arr.length===1?'piece':'pieces'}`;$('#shop-results').className=`product-grid ${filters.view==='list'?'list':''}`;$('#shop-results').innerHTML=arr.length?arr.map(card).join(''):`<div class="empty"><h2>No pieces found.</h2><p>Try another size, colour or price range.</p><button class="btn outline" data-action="clear-filters">Reset filters</button></div>`;
$('#filter-chips').innerHTML=[...filters.cats,filters.size,filters.color,filters.max?`Under ${money(+filters.max)}`:'',filters.available?'In stock':'',filters.query?`Search: ${filters.query}`:''].filter(Boolean).map(t=>`<span class="chip">${esc(t)}</span>`).join('');$('#sort-select').value=filters.sort}
let selected={id:'',color:'',size:'',qty:1,image:0};
function selectProduct(p){selected={id:p.id,color:p.colors[0].name,size:'',qty:1,image:0}}
function productOptions(p){return `<div class="option-label"><span>Colour: <strong id="chosen-color">${esc(selected.color)}</strong></span></div><div class="options">${p.colors.map(c=>`<button class="option color-option ${selected.color===c.name?'selected':''}" data-action="color" data-color="${esc(c.name)}" aria-pressed="${selected.color===c.name}"><span class="swatch" style="background:${esc(c.hex)}"></span> ${esc(c.name)}</button>`).join('')}</div><div class="option-label"><span>Choose your size</span><button class="text-link" data-action="size-guide">Size guide</button></div><div class="options" id="size-options">${sizeOptions(p)}</div><p class="stock" id="stock-message">${stockMessage(p)}</p><div class="purchase-row"><div class="quantity"><button data-action="qty-minus" aria-label="Decrease quantity">−</button><span id="product-qty">${selected.qty}</span><button data-action="qty-plus" aria-label="Increase quantity">+</button></div><button class="btn" data-action="add" id="add-button" ${totalStock(p)===0?'disabled':''}>${totalStock(p)===0?'Out of stock':'Add to bag'}</button></div><button class="btn outline buy-now" data-action="buy" ${totalStock(p)===0?'disabled':''}>Buy now</button><p class="detail-note">Preview item · stock photographs, sample price and variants. Colour options demonstrate selection; photos are styling references.</p>`}
function sizeOptions(p){return p.sizes.map(s=>`<button class="option ${s===selected.size?'selected':''}" data-action="size" data-size="${esc(s)}" ${available(p,selected.color,s)===0?'disabled':''} aria-pressed="${s===selected.size}">${esc(s)}</button>`).join('')}
function stockMessage(p){if(totalStock(p)===0)return 'This piece is currently out of stock in the preview catalogue.';if(!selected.size)return 'Choose a size. Unavailable sizes are crossed out.';const n=available(p,selected.color,selected.size);return n<3?`Only ${n} left in this sample size & colour`:'Available in the preview catalogue'}
function productPage(p){if(!p)return emptyPage('This piece is no longer here.','Explore the rest of the collection.');selectProduct(p);return `<div class="wrap"><div class="breadcrumbs"><a href="/shop">Collection</a> / <a href="/shop?category=${encodeURIComponent(p.category)}">${esc(p.category)}</a> / ${esc(p.name)}</div><section class="product-detail"><div><div class="gallery-main">${picture(p.images[0],`${p.name}, illustrative stock photograph`,'id="main-product-image" width="1000" height="1250" fetchpriority="high"')}<button class="icon-btn zoom" data-action="zoom" aria-label="Zoom product photograph">${icon('zoom')}</button></div><div class="thumbnails">${p.images.map((im,i)=>`<button data-action="thumbnail" data-index="${i}" class="${i===0?'selected':''}" aria-label="View image ${i+1}">${picture(im,`Styling reference ${i+1}`,'width="100" height="125"')}</button>`).join('')}</div><p class="preview-caption">Stock images illustrate the design direction. They do not show Sambecca’s Closet merchandise or the same garment in every image.</p></div><div><p class="eyebrow gold">${esc(p.category)}</p><h1>${esc(p.name)}</h1><p class="price">${money(p.price)}${p.oldPrice>p.price?`<del>${money(p.oldPrice)}</del>`:''}</p><p class="product-desc">${esc(p.description)}</p>${productOptions(p)}<div class="detail-tools"><button data-action="wish" data-id="${p.id}">${icon('heart')} <span id="detail-wish">${wishlist.includes(p.id)?'Saved to wishlist':'Save to wishlist'}</span></button><button data-action="share" data-id="${p.id}">${icon('share')} Share this piece</button></div>${[['Fabric & fit',`${p.fabric} ${p.fit}`],['Care for your piece',p.care],['Delivery & exchanges','Delivery charges, timelines and the exchange policy will be published once confirmed by the brand. See our delivery and returns pages for the current status.']].map(([h,t])=>`<details class="accordion"><summary>${h}</summary><p>${esc(t)}</p></details>`).join('')}</div></section></div>${productSection('A few more you might love.','Complete your closet',data.products.filter(x=>x.id!==p.id).slice(0,4),'/shop')}`}
function emptyPage(h,p){return `<div class="wrap section"><div class="empty"><h2>${h}</h2><p>${p}</p><a class="btn" href="/shop">Explore the collection</a></div></div>`}
function wishPage(){const arr=data.products.filter(p=>wishlist.includes(p.id));return `<div class="wrap section"><div class="section-title"><div><p class="eyebrow gold">Keep your favourites close</p><h1 style="font-size:4rem">Your wishlist.</h1></div></div><div class="product-grid">${arr.length?arr.map(card).join(''):`<div class="empty"><h2>Your next favourite is waiting.</h2><p>Tap the heart on any piece to save it here. Favourites are saved on this browser.</p><a class="btn" href="/shop">Find your favourites</a></div>`}</div></div>`}
function about(){return `<section class="about-hero"><div><p class="eyebrow gold">The story behind the closet</p><h1>Workwear that<br>understands <em>you.</em></h1><p>Smart. Comfortable. Beautifully you.<br>That’s where our story begins.</p></div>${picture(data.settings.storyImage,'Editorial stock photograph, not a photograph of the founder','width="1000" height="1200"')}</section><article class="info-page"><h2>Born from an everyday challenge.</h2><p>As a working woman, our founder often struggled to find corporate tops that looked smart, felt comfortable, fit properly and reflected the confident woman she wanted to be at work.</p><p>Online shopping did not always make it easier. Sometimes the quality did not match the pictures, the prices were too high, or the clothes simply missed the right combination of elegance, comfort and fit.</p><p>Sambecca’s Closet was created to solve that problem. We curate stylish, quality and affordable corporate and business-casual pieces that help working women feel polished, confident and effortlessly work-ready.</p><div class="info-callout">You should be able to dress professionally, look beautiful and feel comfortable without breaking the bank.</div><h2>Our mission</h2><p>To empower corporate women to look elegant, confident and professional every day without overspending.</p><h2>Our vision</h2><p>To become a go-to destination for affordable, stylish women’s corporate wear in Lagos and across Nigeria.</p><h2>Our promise</h2><p>Quality. Comfort. Elegance. Confidence.</p><a class="btn" href="/shop" style="text-decoration:none;margin-top:20px">Discover your next favourite</a></article>${benefits()}`}
function contact(){return `<div class="wrap"><div class="contact-layout"><div><p class="eyebrow gold">We’re here for you</p><h1>Let’s talk<br>about your closet.</h1><p>Need help finding a piece, choosing a size or asking about an order? Get in touch.</p><p>Lagos, Nigeria</p><p><a href="mailto:${esc(data.settings.email)}">${esc(data.settings.email)}</a></p><p><a href="${safeUrl(data.settings.instagram)}" target="_blank" rel="noopener">Instagram: @sambeccaCloset</a><br><a href="${safeUrl(data.settings.tiktok)}" target="_blank" rel="noopener">TikTok: @sambeccas.closet</a></p><button class="btn outline" data-action="support">Chat with us</button></div><div><form id="contact-form"><div class="form-grid"><label class="field">Your name<input name="name" required autocomplete="name"></label><label class="field">Email address<input type="email" name="email" required autocomplete="email"></label></div><label class="field">Phone number (optional)<input type="tel" name="phone" autocomplete="tel"></label><label class="field">How can we help?<select name="subject"><option>Product enquiry</option><option>Help with sizing</option><option>Delivery enquiry</option><option>Other enquiry</option></select></label><label class="field">Your message<textarea name="message" required></textarea></label><button class="btn" type="submit">Prepare email enquiry</button><p class="preview-caption">Opens your email app with your message. It is sent only when you send the email.</p></form></div></div></div>`}
const faqItems=[['How do I place an order?','Browse the collection, choose your colour and size, and add the piece to your bag. This review version lets you explore checkout, but does not accept orders or payments.'],['What payment methods do you accept?','The store’s payment gateway is still to be connected. Card, bank transfer and other available Nigerian payment methods will be confirmed before launch.'],['Do you deliver outside Lagos?','Delivery is planned for Lagos and other locations within Nigeria. Available routes and charges will be confirmed by the brand.'],['How long does delivery take?','Approved delivery timelines will be published before the store opens for orders. Contact us to discuss your location.'],['How do I know my size?','See our size guide for how to take your measurements. Product measurements and size equivalents are awaiting confirmation from the brand.'],['Can I exchange an item if it doesn’t fit?','The final exchange conditions and return period are awaiting brand approval. See the Returns & Exchanges page for the current status.'],['Can I order through WhatsApp?','The official business WhatsApp link will be added once supplied. In the meantime, you can contact us by email or Instagram.'],['Are your products ready-to-wear?','Sambecca’s Closet is an online retailer of curated corporate and business-casual clothing. Actual product availability will be listed in the approved catalogue.'],['How do I track my order?','Order tracking will become available after live order processing is connected. No order is created by this preview.'],['Can I cancel my order?','Cancellation and refund terms will be published after approval. Please contact the brand for help before placing a live order.']];
function infoPage(type){const content={
 'faq':['A little help, right here.','Your questions, answered.',faqItems.map(([h,p])=>`<details class="accordion"><summary>${h}</summary><p>${p}</p></details>`).join('')],
 'size-guide':['Find your fit.','Comfort starts with the right measurements.',`<div class="info-callout">The brand’s exact size chart is awaiting confirmation. Sample S–XL options in the preview are not a sizing recommendation.</div><h2>Take your measurements</h2><div class="scroll-table"><table class="size-table"><thead><tr><th>Measurement</th><th>How to measure</th></tr></thead><tbody><tr><td>Bust</td><td>Measure around the fullest part of your bust, keeping the tape level.</td></tr><tr><td>Waist</td><td>Measure around your natural waist without pulling the tape tight.</td></tr><tr><td>Hips</td><td>Measure around the fullest part of your hips.</td></tr><tr><td>Trouser length</td><td>For an inseam, measure from the crotch seam to the hem on a well-fitting pair. Confirm which length measurement the product uses.</td></tr></tbody></table></div><p>Keep the tape comfortable against your body. Compare your measurements with the final product chart once available. Size labels can vary between styles.</p><a href="/contact">Need help? Contact us before ordering.</a>`],
 'delivery':['From our closet to yours.','Delivery information.',`<div class="info-callout">Delivery charges and timelines are awaiting brand confirmation. No delivery fee is charged in this preview.</div><h2>Where we deliver</h2><p>The brand plans to serve Lagos and other locations within Nigeria. Exact delivery coverage will be confirmed before launch.</p><h2>Your delivery questions</h2><p>Delivery time, local and nationwide charges, any same-day options, tracking and missed-delivery arrangements will be published here once approved.</p><a href="/contact">Ask about your delivery location</a>`],
 'returns':['Let’s get your fit right.','Returns & exchanges.',`<div class="info-callout">The final returns, exchanges and refund policy must be approved by Sambecca’s Closet before the store accepts orders.</div><p>The approved policy will explain the return period, eligible items, garment condition, delivery costs, the exchange process and whether refunds are available.</p><p>Please contact us for guidance on an actual purchase. This review page does not establish a return or refund entitlement.</p><a href="/contact">Contact the brand</a>`],
 'privacy':['Your privacy matters.','Privacy information.',`<div class="info-callout">This is the privacy notice for the review website. A complete store privacy policy will be reviewed before launch.</div><h2>This preview</h2><p>Your shopping bag, wishlist and owner-preview edits are saved in this browser’s local storage. They are not shared with other shoppers or the brand. No customer account is created and no payment details are collected.</p><p>Checkout fields are used only to display a preview summary. They are held in page memory and are not sent to a server. Contact enquiries open your own email app. The newsletter form validates your address but does not subscribe or store it.</p><h2>External services</h2><p>Stock photographs load from Pexels and fonts load from Google Fonts. Your browser sends ordinary connection information to these providers when requesting those assets. Social links open the respective platforms.</p><h2>Clearing your preview data</h2><p>Use the button below to remove saved shopping and owner-preview data from this browser.</p><button class="btn outline" data-action="clear-data">Clear this browser’s preview data</button><p>Questions? Email <a href="mailto:${esc(data.settings.email)}">${esc(data.settings.email)}</a>.</p>`],
 'terms':['Before you shop.','Terms & conditions.',`<div class="info-callout">This website is a client review version. Products, prices, fabrics, stock and photographs are illustrative. It does not accept real orders or payments.</div><p>The live store’s approved terms will cover orders, pricing, payment, delivery, cancellations, returns and customer support. These terms must be completed before checkout is enabled.</p><p>Stock photographs are visual references and do not depict Sambecca’s Closet merchandise. Review labels and demo checkout restrictions should remain in place until the actual catalogue and operational policies are approved.</p><a href="/contact">Contact us with a question</a>`],
 'account':['Your closet, in one place.','Customer accounts.',`<div class="review-status"><h3>Accounts open with the live store.</h3><p>Secure sign-in, saved addresses and order history will be connected before account registration opens. This preview does not collect passwords or create accounts.</p></div><p>You can still save favourites and build a shopping bag on this browser.</p><a class="btn" href="/wishlist" style="text-decoration:none">View your wishlist</a>`]
};const [h,sub,body]=content[type];return `<article class="info-page"><p class="eyebrow">${sub}</p><h1>${h}</h1>${body}</article>`}
function bagLines(){return cart.map(c=>{const p=product(c.id);return `<div class="cart-line">${picture(p.images[0],p.name,'width="76" height="100"')}<div><a href="/product/${p.id}"><h3>${esc(p.name)}</h3></a><p>${esc(c.color)} / ${esc(c.size)} · ${money(p.price)}</p><div class="quantity"><button data-action="bag-minus" data-key="${esc(c.key)}" aria-label="Decrease ${esc(p.name)} quantity">−</button><span>${c.qty}</span><button data-action="bag-plus" data-key="${esc(c.key)}" aria-label="Increase ${esc(p.name)} quantity">+</button></div><button class="remove" data-action="remove" data-key="${esc(c.key)}">Remove</button></div></div>`}).join('')}
function subtotal(){return cart.reduce((a,c)=>a+product(c.id).price*c.qty,0)}
let promo=false;
function totals(){const sub=subtotal(),discount=promo?Math.round(sub*.1):0;return `<div class="totals-row"><span>Subtotal</span><span>${money(sub)}</span></div>${discount?`<div class="totals-row"><span>Preview discount (10%)</span><span>−${money(discount)}</span></div>`:''}<div class="totals-row"><span>Delivery</span><span>To be confirmed</span></div><div class="totals-row total"><span>Items total</span><span>${money(sub-discount)}</span></div>`}
function checkout(){if(!cart.length)return emptyPage('Your bag is waiting.','Find something you love before exploring checkout.');return `<div class="wrap"><div class="page-intro"><p class="eyebrow">The final little details</p><h1>Make it yours.</h1><p>Checkout preview. No payment is taken and no order is placed.</p></div><div class="checkout-layout"><div><p class="checkout-step">1. Your details &nbsp; / &nbsp; 2. Review &nbsp; / &nbsp; Payment opens at launch</p><form id="checkout-form"><h2 style="font-size:2.2rem;margin-bottom:20px">Delivery details</h2><div class="form-grid"><label class="field">First name<input name="firstName" autocomplete="given-name" required></label><label class="field">Last name<input name="lastName" autocomplete="family-name" required></label><label class="field full">Email address<input type="email" name="email" autocomplete="email" required></label><label class="field full">Phone number<input type="tel" name="phone" autocomplete="tel" required></label><label class="field full">Street address<input name="address" autocomplete="street-address" required></label><label class="field">City<input name="city" autocomplete="address-level2" required></label><label class="field">State<select name="state" required><option value="">Select a state</option>${['Abia','Adamawa','Akwa Ibom','Anambra','Bauchi','Bayelsa','Benue','Borno','Cross River','Delta','Ebonyi','Edo','Ekiti','Enugu','FCT Abuja','Gombe','Imo','Jigawa','Kaduna','Kano','Katsina','Kebbi','Kogi','Kwara','Lagos','Nasarawa','Niger','Ogun','Ondo','Osun','Oyo','Plateau','Rivers','Sokoto','Taraba','Yobe','Zamfara'].map(s=>`<option>${s}</option>`).join('')}</select></label><label class="field full">Delivery notes (optional)<textarea name="notes"></textarea></label></div><p class="preview-caption" style="margin:0 0 20px">Use sample details for this walkthrough. Your entries are not sent or stored.</p><button class="btn" type="submit">Review checkout preview</button></form></div><aside class="checkout-card"><h2>Your good choices.</h2><div>${bagLines()}</div><form id="promo-form" class="promo"><label class="skip" for="promo-code">Promo code</label><input id="promo-code" placeholder="Promo code" name="code"><button class="btn small outline">Apply</button></form><p class="preview-caption">Try PREVIEW10 to explore a sample discount.</p><div id="checkout-totals">${totals()}</div><p class="preview-caption">Delivery and live payment methods will be confirmed before launch.</p></aside></div></div>`}
function openPanel(title,body,type='drawer'){const d=$('#panel');if(d.open)d.close();d.className=type;d.setAttribute('aria-labelledby','panel-title');d.innerHTML=`<div class="panel-head"><h2 id="panel-title">${title}</h2><button class="icon-btn close" data-action="close" aria-label="Close dialog">${icon('close')}</button></div><div class="panel-body">${body}</div>`;d.showModal();document.body.classList.add('body-lock')}
function closePanel(){if($('#panel').open)$('#panel').close();document.body.classList.remove('body-lock')}
function openBag(){sanitizeCart();openPanel('Your shopping bag.',cart.length?`${bagLines()}<div style="margin-top:20px">${totals()}</div><a class="btn" href="/checkout">Explore checkout</a><p class="preview-caption">Shopping preview only. No live purchases.</p>`:`<div class="empty"><h2>Room for something lovely.</h2><p>Add a favourite piece to your bag.</p><a class="btn" href="/shop">Discover the collection</a></div>`)}
function quickView(p){selectProduct(p);openPanel(p.name,`${picture(p.images[0],`${p.name}, stock styling reference`,'style="width:100%;height:290px;object-position:center 25%"')}<p class="price">${money(p.price)}</p>${productOptions(p)}<a class="text-link" href="/product/${p.id}">View full details</a>`)}
function updateOptions(){const p=product(selected.id);$('#chosen-color').textContent=selected.color;$('#size-options').innerHTML=sizeOptions(p);$('#stock-message').textContent=stockMessage(p);$('#product-qty').textContent=selected.qty;$$('.color-option').forEach(b=>{b.classList.toggle('selected',b.dataset.color===selected.color);b.setAttribute('aria-pressed',b.dataset.color===selected.color)})}
function addToBag(buy=false){const p=product(selected.id);if(!selected.size){toast('Choose your size first.');$('#size-options').querySelector('button:not(:disabled)')?.focus();return}const limit=available(p,selected.color,selected.size),key=cartKey(p.id,selected.color,selected.size),existing=cart.find(c=>c.key===key);if((existing?.qty||0)+selected.qty>limit){toast('That quantity is not available in this size and colour.');return}if(existing)existing.qty+=selected.qty;else cart.push({key,id:p.id,color:selected.color,size:selected.size,qty:selected.qty});saveBag();shell();if(buy){closePanel();go('/checkout')}else openBag()}
function support(){if(data.settings.whatsapp){window.open(data.settings.whatsapp,'_blank','noopener');return}openPanel('Let’s talk.',`<p>Need help with a style or size? Email us or send a message on Instagram.</p><div class="help-options"><a class="btn" href="mailto:${esc(data.settings.email)}">Email the brand</a><a class="btn outline" href="${safeUrl(data.settings.instagram)}" target="_blank" rel="noopener">Open Instagram</a></div><p class="preview-caption">The official WhatsApp contact will be added once supplied.</p>`,'modal')}
function admin(){return `<div class="wrap section"><div class="admin-top"><div><p class="eyebrow gold">Owner preview workspace</p><h1 style="font-size:3.6rem">Manage your closet.</h1></div><a class="text-link" href="/">View storefront</a></div><div class="admin-banner"><strong>Review editor, on this browser only.</strong> Changes are not published to the live website or shared across devices. Export the catalogue after editing and replace <code>data/catalogue.js</code> in GitHub to share an updated preview. Secure admin access, uploads, orders and analytics require the production backend.</div><div class="admin-stats"><div class="admin-stat"><strong>${data.products.length}</strong><span>Sample styles</span></div><div class="admin-stat"><strong>${data.products.reduce((a,p)=>a+totalStock(p),0)}</strong><span>Sample stock units</span></div><div class="admin-stat"><strong>${data.products.filter(p=>!totalStock(p)).length}</strong><span>Sold-out styles</span></div></div><div class="admin-top"><div style="display:flex;gap:10px;flex-wrap:wrap"><button class="btn small" data-action="new-product">Add a piece</button><button class="btn small outline" data-action="settings">Brand & banner</button><button class="btn small outline" data-action="export">Export catalogue</button><button class="btn small outline" data-action="import">Import catalogue</button><input id="import-file" type="file" accept=".js,.json" hidden></div><button class="text-link" data-action="reset-catalogue">Restore original sample catalogue</button></div><div class="admin-grid">${data.products.map(p=>`<article class="admin-card">${picture(p.images[0],p.name,'loading="lazy"')}<h3>${esc(p.name)}</h3><p>${esc(p.category)}<br>${money(p.price)} · ${totalStock(p)} sample units</p><div style="clear:both"><button class="btn small outline" data-action="edit-product" data-id="${p.id}">Edit piece & stock</button> <button class="text-link" data-action="delete-product" data-id="${p.id}">Remove</button></div></article>`).join('')}</div></div>`}
function editProduct(p){const fresh=!p;p=p||{id:'sc-'+Date.now().toString(36),name:'',category:'Corporate Tops',price:0,oldPrice:0,description:'',fabric:'',fit:'',care:'',images:[],colors:[{name:'Black',hex:'#282828'}],sizes:['S','M','L','XL'],stock:{Black:{S:0,M:0,L:0,XL:0}}};openPanel(fresh?'Add a new piece.':'Edit your piece.',`<form id="product-edit-form" data-id="${p.id}" data-new="${fresh}"><label class="field">Product name<input name="name" value="${esc(p.name)}" required maxlength="100"></label><div class="form-grid"><label class="field">Category<select name="category">${categories.map(c=>`<option ${p.category===c?'selected':''}>${c}</option>`).join('')}</select></label><label class="field">Price (NGN)<input name="price" type="number" min="1" step="1" value="${p.price}" required></label><label class="field">Previous price (0 for no sale)<input name="oldPrice" type="number" min="0" step="1" value="${p.oldPrice}"></label><label class="field">Collection<select name="collection"><option value="none">Regular collection</option><option value="new" ${p.newArrival&&!p.bestSeller?'selected':''}>New arrival</option><option value="best" ${p.bestSeller&&!p.newArrival?'selected':''}>Best seller</option><option value="both" ${p.bestSeller&&p.newArrival?'selected':''}>New & best seller</option></select></label></div><label class="field">Description<textarea name="description" required>${esc(p.description)}</textarea></label><label class="field">Photo URLs (one per line)<textarea name="images" required placeholder="https://... or /assets/images/photo.jpg">${p.images.map(esc).join('\n')}</textarea></label><p class="preview-caption">Use your own approved product photos. Put local images in assets/images and enter their /assets/images/filename path. This editor does not upload images to a server.</p><label class="field">Sizes (comma separated)<input name="sizes" value="${p.sizes.map(esc).join(', ')}" required></label><label class="field">Colours (one per line: name, #hex)<textarea name="colors" required>${p.colors.map(c=>`${esc(c.name)}, ${esc(c.hex)}`).join('\n')}</textarea></label><h3 style="font-size:1.7rem;margin-bottom:10px">Stock per size & colour</h3><p class="preview-caption">For newly added sizes or colours, save once, then reopen to set their stock.</p><table class="stock-table"><thead><tr><th>Colour</th><th>Size</th><th>Quantity</th></tr></thead><tbody>${p.colors.flatMap(c=>p.sizes.map(s=>`<tr><td>${esc(c.name)}</td><td>${esc(s)}</td><td><input name="stock:${esc(c.name)}:${esc(s)}" type="number" min="0" step="1" value="${available(p,c.name,s)}" aria-label="${esc(c.name)} ${esc(s)} stock"></td></tr>`)).join('')}</tbody></table><label class="field">Fabric<input name="fabric" value="${esc(p.fabric)}"></label><label class="field">Fit<input name="fit" value="${esc(p.fit)}"></label><label class="field">Care instructions<input name="care" value="${esc(p.care)}"></label><p class="error" id="editor-error" role="alert"></p><button class="btn" type="submit">Save preview changes</button></form>`,'modal')}
function editSettings(){openPanel('Brand & banner.',`<form id="settings-form"><label class="field">Announcement banner<input name="announcement" value="${esc(data.settings.announcement)}" required></label><label class="field">Brand email<input name="email" type="email" value="${esc(data.settings.email)}" required></label><label class="field">WhatsApp link (leave blank until supplied)<input name="whatsapp" type="url" value="${esc(data.settings.whatsapp)}" placeholder="https://wa.me/234..."></label><label class="field">Hero photo URL<input name="heroImage" value="${esc(data.settings.heroImage)}" required></label><label class="field">Story photo URL<input name="storyImage" value="${esc(data.settings.storyImage)}" required></label><p class="error" id="editor-error" role="alert"></p><button class="btn" type="submit">Save preview settings</button></form>`,'modal')}
function saveCatalogue(){const ok=store.write('sc-catalogue-v1',data);sanitizeCart();closePanel();render();toast(ok?'Preview updated on this browser. Export to share it.':'Updated for this session. Browser storage is unavailable; export now.')}
function currentPath(){return location.pathname}
function go(u){closePanel();history.pushState({},'',u);render();window.scrollTo({top:0,behavior:'instant'});$('#main').focus({preventScroll:true})}
function render(){sanitizeCart();shell();const p=currentPath();let html,title;
if(p==='/'||p==='/index.html'){html=home();title='Elevate Your Work Wardrobe'}
else if(p==='/shop'){initFilters();html=shop();title='Shop the Collection'}
else if(p.startsWith('/product/')){const pr=product(p.split('/')[2]);html=productPage(pr);title=pr?.name||'Product'}
else if(p==='/wishlist'){html=wishPage();title='Your Wishlist'}
else if(p==='/about'){html=about();title='Our Story'}
else if(p==='/contact'){html=contact();title='Contact'}
else if(p==='/checkout'){html=checkout();title='Checkout Preview'}
else if(p==='/admin'){html=admin();title='Owner Preview'}
else if(['faq','size-guide','delivery','returns','privacy','terms','account'].includes(p.slice(1))){html=infoPage(p.slice(1));title=p.slice(1).replaceAll('-',' ')}
else{html=emptyPage('Let’s find your way back.','This page is not in the closet.');title='Page Not Found'}
$('#main').innerHTML=html;document.title=`${title} | Sambecca’s Closet`;if(p==='/shop')updateResults();}
$('#panel').addEventListener('close',()=>document.body.classList.remove('body-lock'));
$('#panel').addEventListener('click',e=>{if(e.target===$('#panel')){const r=$('#panel').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closePanel()}});
document.addEventListener('click',async e=>{
const a=e.target.closest('a');if(a&&a.getAttribute('href')?.startsWith('/')&&!e.ctrlKey&&!e.metaKey&&!e.shiftKey&&!e.altKey){e.preventDefault();go(a.getAttribute('href'));return}
const b=e.target.closest('[data-action]');if(!b)return;const act=b.dataset.action,p=product(selected.id);
if(act==='close')closePanel();
else if(act==='bag')openBag();
else if(act==='menu')openPanel('Sambecca’s Closet',`<nav class="menu-links" aria-label="Mobile navigation">${[['/','Home'],['/shop','Shop the collection'],['/shop?collection=new','New arrivals'],['/shop?collection=best','Best sellers'],['/about','Our story'],['/contact','Contact'],['/account','My account']].map(([u,t])=>`<a href="${u}">${t}</a>`).join('')}</nav>`);
else if(act==='support')support();
else if(act==='search'){openPanel('Find your next favourite.',`<input class="search-field" id="search-input" placeholder="Try shirts, trousers, sets…" aria-label="Search products"><div class="search-results" id="search-results"><p class="muted">Start typing to explore the collection.</p></div>`,'modal');$('#search-input').focus()}
else if(act==='quick')quickView(product(b.dataset.id));
else if(act==='wish'){const id=b.dataset.id;wishlist=wishlist.includes(id)?wishlist.filter(x=>x!==id):[...wishlist,id];saveBag();shell();$$(`[data-action="wish"][data-id="${id}"]`).forEach(x=>{x.classList.toggle('saved',wishlist.includes(id));x.setAttribute('aria-pressed',wishlist.includes(id));x.setAttribute('aria-label',`${wishlist.includes(id)?'Remove from':'Add to'} wishlist: ${product(id).name}`)});if($('#detail-wish'))$('#detail-wish').textContent=wishlist.includes(id)?'Saved to wishlist':'Save to wishlist';if(currentPath()==='/wishlist')render();toast(wishlist.includes(id)?'Saved to your wishlist.':'Removed from your wishlist.')}
else if(act==='color'){selected.color=b.dataset.color;selected.size='';selected.qty=1;updateOptions()}
else if(act==='size'){selected.size=b.dataset.size;selected.qty=1;updateOptions()}
else if(act==='qty-minus'){selected.qty=Math.max(1,selected.qty-1);updateOptions()}
else if(act==='qty-plus'){if(!selected.size){toast('Choose your size first.');return}selected.qty=Math.min(available(p,selected.color,selected.size),selected.qty+1);updateOptions()}
else if(act==='add'||act==='buy')addToBag(act==='buy');
else if(['bag-minus','bag-plus','remove'].includes(act)){const c=cart.find(x=>x.key===b.dataset.key);if(!c)return;if(act==='remove')cart=cart.filter(x=>x.key!==c.key);else if(act==='bag-minus'){if(c.qty>1)c.qty--;else cart=cart.filter(x=>x.key!==c.key)}else{if(c.qty>=available(product(c.id),c.color,c.size)){toast('You’ve reached the available quantity.');return}c.qty++}saveBag();shell();if($('#panel').open)openBag();if(currentPath()==='/checkout')render()}
else if(act==='size-guide')openPanel('A comfortable fit.',`<p>The brand’s exact size chart is awaiting confirmation.</p><p style="margin-top:16px">Measure your bust, natural waist and fullest hips. Compare them with the final garment chart before ordering.</p><a class="btn outline" href="/size-guide">Read the size guide</a>`,'modal');
else if(act==='thumbnail'){selected.image=+b.dataset.index;$('#main-product-image').src=p.images[selected.image];$$('.thumbnails button').forEach((x,i)=>x.classList.toggle('selected',i===selected.image))}
else if(act==='zoom'){openPanel('Styling reference',picture(p.images[selected.image],p.name),'zoom-modal')}
else if(act==='share'){const url=`${location.origin}/product/${b.dataset.id}`;try{if(navigator.share)await navigator.share({title:product(b.dataset.id).name,url});else{await navigator.clipboard.writeText(url);toast('Product link copied.')}}catch{toast('Copy this page’s address to share the piece.')}}
else if(act==='filters'){$('#filters').classList.toggle('open');b.setAttribute('aria-expanded',$('#filters').classList.contains('open'))}
else if(act==='clear-filters'){const coll=new URLSearchParams(location.search).get('collection');go('/shop'+(coll?'?collection='+coll:''))}
else if(act==='grid'||act==='list'){filters.view=act;updateResults();$$('[data-action="grid"],[data-action="list"]').forEach(x=>x.setAttribute('aria-pressed',x.dataset.action===act))}
else if(act==='new-product')editProduct();
else if(act==='edit-product')editProduct(product(b.dataset.id));
else if(act==='settings')editSettings();
else if(act==='delete-product'){const id=b.dataset.id;openPanel('Remove this piece?',`<p>${esc(product(id).name)} will be removed from this browser’s preview catalogue.</p><button class="btn" data-action="confirm-delete" data-id="${id}">Remove piece</button><button class="btn outline" data-action="close">Keep piece</button>`,'modal')}
else if(act==='confirm-delete'){data.products=data.products.filter(p=>p.id!==b.dataset.id);saveCatalogue()}
else if(act==='export'){const blob=new Blob(['/* Approved preview catalogue export. */\nwindow.CLOSET_DATA = '+JSON.stringify(data,null,2)+';\n'],{type:'text/javascript'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='catalogue.js';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),2000);toast('Catalogue exported. Replace data/catalogue.js to publish these edits.')}
else if(act==='import')$('#import-file').click();
else if(act==='reset-catalogue')openPanel('Restore the original catalogue?',`<p>This replaces the catalogue edits saved on this browser. Export first if you want to keep them.</p><button class="btn" data-action="confirm-reset">Restore original</button><button class="btn outline" data-action="close">Keep my changes</button>`,'modal');
else if(act==='confirm-reset'){data=clone(window.CLOSET_DATA);saveCatalogue()}
else if(act==='clear-data')openPanel('Clear your preview data?',`<p>Remove the shopping bag, wishlist and owner-preview edits saved on this browser.</p><button class="btn" data-action="confirm-clear">Clear preview data</button><button class="btn outline" data-action="close">Keep my data</button>`,'modal');
else if(act==='confirm-clear'){['sc-catalogue-v1','sc-bag-v1','sc-wishlist-v1'].forEach(k=>{try{localStorage.removeItem(k)}catch{}});data=clone(window.CLOSET_DATA);cart=[];wishlist=[];promo=false;closePanel();render();toast('Preview data cleared.')}
});
document.addEventListener('input',e=>{if(e.target.id==='search-input'){const q=e.target.value.trim().toLowerCase(),arr=data.products.filter(p=>`${p.name} ${p.category}`.toLowerCase().includes(q));$('#search-results').innerHTML=!q?'<p class="muted">Start typing to explore the collection.</p>':arr.length?arr.map(p=>`<a href="/product/${p.id}">${picture(p.images[0],p.name)}<div><strong>${esc(p.name)}</strong><small>${money(p.price)} · ${esc(p.category)}</small></div></a>`).join(''):'<p class="muted">No matches yet. Try another style.</p>'}});
document.addEventListener('change',async e=>{const t=e.target;if(t.closest('#filters')||t.id==='sort-select'){filters.cats=$$('input[name="category"]:checked').map(x=>x.value);filters.size=$('#size-filter').value;filters.color=$('#color-filter').value;filters.max=$('#price-filter').value;filters.available=$('#availability-filter').checked;filters.sort=$('#sort-select').value;updateResults()}
if(t.id==='import-file'&&t.files[0]){try{if(t.files[0].size>2000000)throw Error();let text=await t.files[0].text();text=text.replace(/^\/\*[\s\S]*?\*\/\s*/,'').replace(/^window\.CLOSET_DATA\s*=\s*/,'').replace(/;\s*$/,'');const d=JSON.parse(text);if(!validCatalogue(d))throw Error();data=d;saveCatalogue()}catch{toast('Import failed. Choose a valid exported catalogue.js or catalogue JSON.')}}});
document.addEventListener('submit',e=>{const f=e.target;e.preventDefault();const fd=new FormData(f);
if(f.id==='newsletter-form'){toast('Preview checked. Newsletter signup opens at launch.');f.reset()}
else if(f.id==='contact-form'){const subject=`Sambecca’s Closet: ${fd.get('subject')}`,body=`Name: ${fd.get('name')}\nEmail: ${fd.get('email')}\nPhone: ${fd.get('phone')}\n\n${fd.get('message')}`;location.href=`mailto:${data.settings.email}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;toast('Your email draft is ready. Send it from your email app.')}
else if(f.id==='promo-form'){const code=String(fd.get('code')).trim().toUpperCase();promo=code==='PREVIEW10';$('#checkout-totals').innerHTML=totals();toast(promo?'Sample 10% discount applied.':'That preview code isn’t available. Try PREVIEW10.')}
else if(f.id==='checkout-form'){openPanel('Your checkout preview.',`<div class="info-callout">This is a walkthrough, not an order confirmation. Nothing has been purchased.</div><p><strong>Delivery preview</strong><br>${esc(fd.get('firstName'))} ${esc(fd.get('lastName'))}<br>${esc(fd.get('address'))}<br>${esc(fd.get('city'))}, ${esc(fd.get('state'))}</p><div style="margin:20px 0">${totals()}</div><p>Shipping charges and payment methods will be available once the live store is connected.</p><a class="btn" href="/shop">Continue exploring</a>`,'modal')}
else if(f.id==='product-edit-form'){try{const sizes=String(fd.get('sizes')).split(',').map(s=>s.trim()).filter(Boolean),colors=String(fd.get('colors')).split('\n').filter(s=>s.trim()).map(s=>{const [name,hex]=s.split(',').map(x=>x.trim());return {name,hex}}),images=String(fd.get('images')).split('\n').map(s=>s.trim()).filter(Boolean);if(new Set(sizes).size!==sizes.length||new Set(colors.map(c=>c.name)).size!==colors.length||sizes.length>20||colors.length>20)throw Error('Use unique size and colour names, up to 20 each.');const stock={};for(const c of colors){stock[c.name]={};for(const s of sizes){const n=Number(fd.get(`stock:${c.name}:${s}`)||0);if(!Number.isInteger(n)||n<0)throw Error('Stock must be a whole number of zero or more.');stock[c.name][s]=n}}const coll=fd.get('collection'),p={id:f.dataset.id,name:fd.get('name'),category:fd.get('category'),price:Number(fd.get('price')),oldPrice:Number(fd.get('oldPrice')||0),newArrival:coll==='new'||coll==='both',bestSeller:coll==='best'||coll==='both',description:fd.get('description'),fabric:fd.get('fabric'),fit:fd.get('fit'),care:fd.get('care'),images,colors,sizes,stock};if(!validCatalogue({...data,products:[p]}))throw Error('Check prices, photo URLs and colour hex codes.');const i=data.products.findIndex(x=>x.id===p.id);if(i<0)data.products.push(p);else data.products[i]=p;saveCatalogue()}catch(err){$('#editor-error').textContent=err.message}}
else if(f.id==='settings-form'){const whatsapp=String(fd.get('whatsapp')).trim();if(whatsapp&&!/^https:\/\/(wa\.me\/\d+|api\.whatsapp\.com\/send\?)/.test(whatsapp)){$('#editor-error').textContent='Use an official https://wa.me/ link or leave blank.';return}for(const k of ['heroImage','storyImage'])if(!/^(https?:\/\/|\/assets\/)/.test(fd.get(k))){$('#editor-error').textContent='Enter an https photo URL or /assets/ image path.';return}for(const k of ['announcement','email','whatsapp','heroImage','storyImage'])data.settings[k]=String(fd.get(k)).trim();saveCatalogue()}
});
window.addEventListener('popstate',()=>{closePanel();render()});render();
